import asyncio
import signal
import re
from typing import Optional, Dict, Tuple
from dataclasses import dataclass, field

@dataclass
class HTTPRequest:
    method: str = ""
    path: str = ""
    version: str = ""
    headers: Dict[str, str] = field(default_factory=dict)
    body: bytes = b""
    raw_header_list: list = field(default_factory=list)

@dataclass
class PaymentTransaction:
    transaction_id: str
    amount: float
    currency: str
    status: str = "pending"

class HTTPParser:
    """HTTP/1.1 parser with support for pipelined requests."""

    def __init__(self):
        self._buffer = b""
        self._max_header_size = 8192
        self._max_body_size = 1048576

    def feed(self, data: bytes):
        self._buffer += data

    def _parse_request_line(self, line: bytes) -> Tuple[str, str, str]:
        parts = line.decode('ascii', errors='replace').split(' ', 2)
        if len(parts) != 3:
            raise ValueError("Malformed request line")
        return parts[0], parts[1], parts[2].strip()

    def _determine_body_length(self, headers: Dict[str, str], raw_headers: list) -> int:
        """Determine message body length per RFC 7230 Section 3.3.3.

        Priority: Transfer-Encoding > Content-Length
        When both are present, Transfer-Encoding takes precedence.
        """
        te_value = None
        cl_value = None

        for name, value in raw_headers:
            lower_name = name.lower().strip()
            if lower_name == "transfer-encoding":
                te_value = value.strip()
            elif lower_name == "content-length":
                cl_value = value.strip()

        if te_value and "chunked" in te_value.lower():
            return -1  # chunked encoding

        if cl_value is not None:
            try:
                length = int(cl_value)
                if length < 0:
                    raise ValueError("Negative Content-Length")
                return length
            except ValueError:
                return 0

        return 0

    def _read_chunked_body(self, data: bytes) -> Tuple[Optional[bytes], int]:
        """Parse chunked transfer encoding. Returns (body, bytes_consumed)."""
        body = b""
        pos = 0
        while pos < len(data):
            crlf_pos = data.find(b"\r\n", pos)
            if crlf_pos == -1:
                return None, 0
            chunk_size_str = data[pos:crlf_pos].decode('ascii', errors='replace').strip()
            # Handle chunk extensions
            if ';' in chunk_size_str:
                chunk_size_str = chunk_size_str.split(';')[0]
            try:
                chunk_size = int(chunk_size_str, 16)
            except ValueError:
                raise ValueError(f"Invalid chunk size: {chunk_size_str}")

            if chunk_size == 0:
                # Skip trailing CRLF after last chunk
                end_pos = crlf_pos + 2
                if end_pos + 2 <= len(data):
                    end_pos += 2
                return body, end_pos

            chunk_start = crlf_pos + 2
            chunk_end = chunk_start + chunk_size
            if chunk_end + 2 > len(data):
                return None, 0
            body += data[chunk_start:chunk_end]
            pos = chunk_end + 2

        return None, 0

    def parse_one(self) -> Optional[HTTPRequest]:
        """Parse one complete HTTP request from the buffer."""
        header_end = self._buffer.find(b"\r\n\r\n")
        if header_end == -1:
            return None

        header_section = self._buffer[:header_end]
        lines = header_section.split(b"\r\n")

        if not lines:
            return None

        method, path, version = self._parse_request_line(lines[0])

        headers = {}
        raw_headers = []
        for line in lines[1:]:
            if b":" in line:
                name, _, value = line.partition(b":")
                name_str = name.decode('ascii', errors='replace')
                value_str = value.decode('ascii', errors='replace').strip()
                headers[name_str.lower()] = value_str
                raw_headers.append((name_str, value_str))

        body_start = header_end + 4
        body_length = self._determine_body_length(headers, raw_headers)

        if body_length == -1:
            # Chunked encoding
            result = self._read_chunked_body(self._buffer[body_start:])
            if result[0] is None:
                return None
            body, consumed = result
            self._buffer = self._buffer[body_start + consumed:]
        elif body_length > 0:
            if len(self._buffer) - body_start < body_length:
                return None
            body = self._buffer[body_start:body_start + body_length]
            self._buffer = self._buffer[body_start + body_length:]
        else:
            body = b""
            self._buffer = self._buffer[body_start:]

        req = HTTPRequest(
            method=method,
            path=path,
            version=version,
            headers=headers,
            body=body,
            raw_header_list=raw_headers
        )
        return req


class PaymentProcessor:
    """Handles payment API requests."""

    def __init__(self):
        self._transactions: Dict[str, PaymentTransaction] = {}
        self._next_id = 1000

    def process_payment(self, amount: float, currency: str) -> PaymentTransaction:
        tid = f"TXN-{self._next_id:06d}"
        self._next_id += 1
        txn = PaymentTransaction(
            transaction_id=tid,
            amount=amount,
            currency=currency,
            status="completed"
        )
        self._transactions[tid] = txn
        return txn

    def refund(self, transaction_id: str) -> Optional[PaymentTransaction]:
        txn = self._transactions.get(transaction_id)
        if txn and txn.status == "completed":
            txn.status = "refunded"
            return txn
        return None


class PaymentServer:
    """HTTP server for payment processing with graceful shutdown."""

    def __init__(self, host: str = "0.0.0.0", port: int = 8443):
        self.host = host
        self.port = port
        self.processor = PaymentProcessor()
        self._shutting_down = False
        self._active_connections = set()
        self._server = None

    async def handle_connection(self, reader: asyncio.StreamReader, writer: asyncio.StreamWriter):
        self._active_connections.add(writer)
        parser = HTTPParser()

        try:
            while not self._shutting_down:
                data = await asyncio.wait_for(reader.read(4096), timeout=30.0)
                if not data:
                    break

                parser.feed(data)

                while True:
                    request = parser.parse_one()
                    if request is None:
                        break

                    response = await self._route_request(request)
                    writer.write(response)
                    await writer.drain()
        except (asyncio.TimeoutError, ConnectionResetError):
            pass
        finally:
            self._active_connections.discard(writer)
            writer.close()

    async def _route_request(self, request: HTTPRequest) -> bytes:
        if request.path == "/api/v1/payment" and request.method == "POST":
            return await self._handle_payment(request)
        elif request.path.startswith("/api/v1/refund/") and request.method == "POST":
            return await self._handle_refund(request)
        elif request.path == "/health":
            return self._build_response(200, '{"status": "ok"}')
        else:
            return self._build_response(404, '{"error": "not found"}')

    async def _handle_payment(self, request: HTTPRequest) -> bytes:
        try:
            import json
            data = json.loads(request.body)
            amount = float(data.get("amount", 0))
            currency = data.get("currency", "USD")

            if amount <= 0 or amount > 999999.99:
                return self._build_response(400, '{"error": "invalid amount"}')

            txn = self.processor.process_payment(amount, currency)
            resp_body = json.dumps({
                "transaction_id": txn.transaction_id,
                "amount": txn.amount,
                "currency": txn.currency,
                "status": txn.status
            })
            return self._build_response(200, resp_body)
        except (json.JSONDecodeError, TypeError, ValueError):
            return self._build_response(400, '{"error": "invalid request body"}')

    async def _handle_refund(self, request: HTTPRequest) -> bytes:
        import json
        txn_id = request.path.split("/")[-1]
        if not re.match(r'^TXN-\d{6}$', txn_id):
            return self._build_response(400, '{"error": "invalid transaction id"}')

        txn = self.processor.refund(txn_id)
        if txn:
            return self._build_response(200, json.dumps({"status": "refunded", "transaction_id": txn_id}))
        return self._build_response(404, '{"error": "transaction not found"}')

    def _build_response(self, status: int, body: str) -> bytes:
        status_text = {200: "OK", 400: "Bad Request", 404: "Not Found"}.get(status, "Unknown")
        resp = f"HTTP/1.1 {status} {status_text}\r\n"
        resp += f"Content-Length: {len(body.encode())}\r\n"
        resp += "Content-Type: application/json\r\n"
        resp += "Connection: keep-alive\r\n"
        resp += "\r\n"
        resp += body
        return resp.encode()

    async def start(self):
        self._server = await asyncio.start_server(
            self.handle_connection, self.host, self.port
        )
        loop = asyncio.get_event_loop()
        loop.add_signal_handler(signal.SIGTERM, lambda: asyncio.ensure_future(self.shutdown()))
        loop.add_signal_handler(signal.SIGINT, lambda: asyncio.ensure_future(self.shutdown()))

        async with self._server:
            await self._server.serve_forever()

    async def shutdown(self):
        self._shutting_down = True
        self._server.close()
        # Wait for active connections to finish
        if self._active_connections:
            await asyncio.sleep(5)
            for writer in self._active_connections:
                writer.close()


if __name__ == "__main__":
    server = PaymentServer()
    asyncio.run(server.start())
